module Controller_2_Beh (  output		Ready,   output reg 	Load_regs,   				Add_shift,  input			Start, Zero, clock, reset_b);  parameter	S_idle = 0, S_running = 1;  reg  			state, next_state;  assign		Ready = (state == S_idle);  always @ (posedge clock, negedge reset_b)    if (reset_b == 0) state <= S_idle;    else state <= next_state;  always @ (state, Start, Zero) begin    next_state = S_idle;    Load_regs = 0;    Add_shift = 0;    case (state)      S_idle:			if (Start) begin Load_regs = 1; next_state = S_running; end      S_running:	if (Zero) next_state = S_idle;					else begin Add_shift = 1; next_state = S_running; end    endcase				   endendmodule